val log = LoggerFactory.getLogger("no.nav.emottak.ebms.async.App")

private val HAR_BORGER_FRIKORT_MENGDE_TIMEOUT = 90.seconds

fun main() = SuspendApp {
    val config = config()

    val database = Database(ebmsDbConfig.value)
    database.migrate(ebmsMigrationConfig.value)
    val payloadRepository = PayloadRepository(database)
    val messageReceivedRepository = MessageReceivedRepository(database)
    val messagePendingAckRepository = MessagePendingAckRepository(database, config.messageResendPolicy.resendInterval, config.messageResendPolicy.maxResends)

    val appMicrometerRegistry = PrometheusMeterRegistry(PrometheusConfig.DEFAULT)
    val failedMessageQueue = FailedMessageKafkaHandler(meterRegistry = appMicrometerRegistry)

    val processingService = ProcessingService(
        httpClient = PayloadProcessingClient(scopedAuthHttpClient(EBMS_PAYLOAD_SCOPE))
    )
    val cpaValidationService = CPAValidationService(
        httpClient = CpaRepoClient(scopedAuthHttpClient(EBMS_CPA_REPO_SCOPE))
    )
    val sendInService = SendInService(
        httpClient = SendInClient(
            scopedAuthHttpClient(EBMS_SEND_IN_SCOPE),
            mapOf(MessageType.HAR_BORGER_FRIKORT_MENGDE.serviceName to HAR_BORGER_FRIKORT_MENGDE_TIMEOUT.inWholeMilliseconds)
        )
    )

    val ebmsSignalProducer = EbmsMessageProducer(config.kafkaSignalProducer.topic, config.kafka)
    val ebmsPayloadProducer = EbmsMessageProducer(config.kafkaPayloadProducer.topic, config.kafka)
    val ebmsInPayloadProducer = EbmsMessageProducer(config.kafkaEbmsInPayloadProducer.topic, config.kafka)

    val smtpTransportClient = SmtpTransportClient(scopedAuthHttpClient(SMTP_TRANSPORT_SCOPE))

    val eventRegistrationService = EventRegistrationServiceImpl(
        EventLoggingService(config().eventLogging, EventPublisherClient(config().kafka))
    )

    val payloadMessageForwardingService = PayloadMessageForwardingService(
        sendInService = sendInService,
        cpaValidationService = cpaValidationService,
        processingService = processingService,
        payloadRepository = payloadRepository,
        ebmsPayloadProducer = ebmsPayloadProducer,
        ebmsInPayloadProducer = ebmsInPayloadProducer,
        eventRegistrationService = eventRegistrationService,
        messagePendingAckRepository = messagePendingAckRepository,
        ebmsHttpDeliveryClient = EbmsHttpDeliveryClient(ebxmlHttpDeliveryClient())
    )

    val retryService = RetryService(
        cpaValidationService = cpaValidationService,
        eventRegistrationService = eventRegistrationService,
        failedMessageKafkaHandler = failedMessageQueue,
        signalSender = { ebmsDocument, signalResponderEmails ->
            sendSignalResponseToTopic(ebmsSignalProducer, eventRegistrationService, ebmsDocument, signalResponderEmails)
        }
    )

    val payloadMessageService = PayloadMessageService(
        cpaValidationService = cpaValidationService,
        processingService = processingService,
        ebmsSignalProducer = ebmsSignalProducer,
        payloadMessageForwardingService = payloadMessageForwardingService,
        eventRegistrationService = eventRegistrationService,
        messageReceivedRepository = messageReceivedRepository,
        retryService = retryService,
        messagePendingAckRepository = messagePendingAckRepository
    )

    val signalMessageService = SignalMessageService(
        cpaValidationService = cpaValidationService,
        eventRegistrationService = eventRegistrationService,
        messagePendingAckRepository = messagePendingAckRepository
    )

    val messageFilterService = MessageFilterService(
        payloadMessageService = payloadMessageService,
        signalMessageService = signalMessageService,
        smtpTransportClient = smtpTransportClient,
        eventRegistrationService = eventRegistrationService,
        failedMessageKafkaHandler = failedMessageQueue
    )

    val pauseRetryErrorsTimerFlag = PauseRetryErrorsTimerFlag()
    val leadership = createLeadership(appMicrometerRegistry)
    val leaderForwarder = createLeaderForwarder(leadership)

    try {
        result {
            resourceScope {
                launch { leadership.watch() }
                launchRetryConsumers(config, failedMessageQueue, leadership)
                launchSignalReceiver(
                    config = config,
                    messageFilterService = messageFilterService
                )
                launchPayloadReceiver(
                    config = config,
                    messageFilterService = messageFilterService
                )
                launchEbmsOutPayloadReceiver(
                    config = config,
                    payloadMessageService = payloadMessageService
                )
                launchErrorRetryTaskIncoming(
                    config = config,
                    retryService = retryService,
                    messageFilterService = messageFilterService,
                    pauseRetryErrorsTimerFlag = pauseRetryErrorsTimerFlag,
                    leadership = leadership
                )
                launchErrorRetryTaskOutgoing(
                    config = config,
                    retryService = retryService,
                    payloadMessageService = payloadMessageService,
                    pauseRetryErrorsTimerFlag = pauseRetryErrorsTimerFlag,
                    leadership = leadership
                )
                launchMesssageResendTask(
                    config = config,
                    messagePendingAckRepository = messagePendingAckRepository,
                    payloadMessageForwardingService = payloadMessageForwardingService,
                    meterRegistry = appMicrometerRegistry,
                    leadership = leadership
                )
                launchCleanupPayloadsTask(
                    config = config,
                    payloadRepository = payloadRepository
                )

                server(
                    Netty,
                    port = 8080,
                    module = {
                        ebmsProviderModule(
                            payloadRepository = payloadRepository,
                            messageFilterService = messageFilterService,
                            eventRegistrationService = eventRegistrationService,
                            retryService = retryService,
                            payloadMessageService = payloadMessageService,
                            pauseRetryErrorsTimerFlag = pauseRetryErrorsTimerFlag,
                            messagePendingAckRepository = messagePendingAckRepository,
                            appMicrometerRegistry = appMicrometerRegistry,
                            leaderForwarder = leaderForwarder
                        )
                    }
                ).also { it.engineConfig.maxChunkSize = 100000 }

                awaitCancellation()
            }
        }
            .onFailure { error ->
                when (error) {
                    is CancellationException -> {} // expected behaviour - normal shutdown
                    else -> log.error("Unexpected shutdown initiated", error)
                }
            }
    } finally {
        leaderForwarder?.close()
        leadership.close()
        failedMessageQueue.close()
        ebmsSignalProducer.close()
        ebmsPayloadProducer.close()
        ebmsInPayloadProducer.close()
    }
}

class PauseRetryErrorsTimerFlag {
    @Volatile
    var paused = false
}

fun CoroutineScope.launchRetryConsumers(config: Config, failedMessageQueue: FailedMessageKafkaHandler, leadership: Leadership) =
    launch {
        leadership.leader.collectLatest { leader ->
            if (leader == leadership.podName) {
                coroutineScope {
                    if (config.kafkaErrorQueue.active) {
                        launch { failedMessageQueue.runRetryConsumer(Direction.IN) { leadership.isLeader } }
                    }
                    if (config.kafkaErrorQueueOut.active) {
                        launch { failedMessageQueue.runRetryConsumer(Direction.OUT) { leadership.isLeader } }
                    }
                    awaitCancellation()
                }
            }
        }
    }

fun CoroutineScope.launchPayloadReceiver(
    config: Config,
    messageFilterService: MessageFilterService
) {
    if (config.kafkaPayloadReceiver.active) {
        launch(Dispatchers.IO) {
            startPayloadReceiver(
                config.kafkaPayloadReceiver.topic,
                config.kafka,
                messageFilterService
            )
        }
    }
}

fun CoroutineScope.launchEbmsOutPayloadReceiver(
    config: Config,
