            )
        }
    }
}

fun CoroutineScope.launchSignalReceiver(
    config: Config,
    messageFilterService: MessageFilterService
) {
    if (config.kafkaSignalReceiver.active) {
        launch(Dispatchers.IO) {
            startSignalReceiver(
                config.kafkaSignalReceiver.topic,
