}

/**
 * Builds the OUT-direction retry processor lambda.
 * Decodes the stored SendInResponse from the record and delegates to
 * [PayloadMessageService.processOutboundResponse], mirroring the live receive path in EbmsOutPayloadReceiver.
 */
fun makeOutRetryProcessor(
    payloadMessageService: PayloadMessageService
): suspend (ReceiverRecord<String, ByteArray>) -> Unit = { record ->
    val sendInResponse = LENIENT_JSON_PARSER.decodeFromString<SendInResponse>(record.value().decodeToString())
    val payloadMessage = PayloadMessage(
        requestId = sendInResponse.requestId,
        messageId = sendInResponse.messageId,
        conversationId = sendInResponse.conversationId,
        cpaId = sendInResponse.cpaId,
        addressing = sendInResponse.addressing,
        payload = Payload(sendInResponse.payload, ContentType.Application.Xml.toString()),
        refToMessageId = sendInResponse.refToMessageId,
        duplicateElimination = false,
        ackRequested = true
    )
    payloadMessageService.processOutboundResponse(record, payloadMessage)
}

fun CoroutineScope.launchErrorRetryTaskIncoming(
    config: Config,
    retryService: RetryService,
    messageFilterService: MessageFilterService,
    pauseRetryErrorsTimerFlag: PauseRetryErrorsTimerFlag,
    leadership: Leadership
) {
    if (!config.kafkaErrorQueue.active) return

    launchLeaderSchedule(
        name = "Incoming retries",
        startupDelay = config.errorRetryPolicyIncoming.startupDelay,
        interval = config.errorRetryPolicyIncoming.processInterval,
        leadership = leadership
    ) {
        if (!pauseRetryErrorsTimerFlag.paused) {
            retryService.consumeRetryQueueIncoming(
                limit = config.errorRetryPolicyIncoming.maxMessagesToProcess,
                processor = messageFilterService::filterMessage
            )
        }
    }
}

fun CoroutineScope.launchErrorRetryTaskOutgoing(
    config: Config,
    retryService: RetryService,
    payloadMessageService: PayloadMessageService,
    pauseRetryErrorsTimerFlag: PauseRetryErrorsTimerFlag,
    leadership: Leadership
) {
    if (!config.kafkaErrorQueueOut.active) return

    launchLeaderSchedule(
        name = "Outgoing retries",
        startupDelay = config.errorRetryPolicyOutgoing.startupDelay,
        interval = config.errorRetryPolicyOutgoing.processInterval,
        leadership = leadership
    ) {
        if (!pauseRetryErrorsTimerFlag.paused) {
            retryService.consumeRetryQueueOutgoing(
                limit = config.errorRetryPolicyOutgoing.maxMessagesToProcess,
                processor = makeOutRetryProcessor(payloadMessageService)
            )
        }
    }
}

fun CoroutineScope.launchCleanupPayloadsTask(
    config: Config,
    payloadRepository: PayloadRepository
) {
    if (!config.cleanupPayloadsJob.enabled) return
    val cleanupPayloadsIsRunning = AtomicBoolean(false)
    val initialDelay = config.cleanupPayloadsJob.startAtTime.value.durationUntil()
    val readableInterval = config.cleanupPayloadsJob.fixedInterval.readableInterval()
    log.info("Delaying initial payload cleanup by ${initialDelay.readableInterval()}, running every $readableInterval after that")
    fixedRateTimer(
        name = "Cleanup Payloads Timer Job",
        initialDelay = initialDelay.inWholeMilliseconds,
        period = config.cleanupPayloadsJob.fixedInterval.inWholeMilliseconds,
        daemon = true
    ) {
        launch(Dispatchers.IO) {
            if (!cleanupPayloadsIsRunning.compareAndSet(false, true)) {
                log.info("Previous CleanupPayloadsJob is still running, skip starting a new one.")
                return@launch
            }
            log.info("=== CleanupPayloadsJob starting...")
            try {
                val deleted = payloadRepository.cleanupOldPayloads(
                    config.cleanupPayloadsJob.keepPayloadsDays.value,
                    config.cleanupPayloadsJob.batchSize.value.toInt()
                )
                log.info("CleanupPayloadsJob deleted $deleted payload(s) older than ${config.cleanupPayloadsJob.keepPayloadsDays.value} days")
            } catch (e: Exception) {
                log.error("CleanupPayloadsJob failed", e)
            } finally {
                cleanupPayloadsIsRunning.set(false)
            }
        }
    }
}

fun CoroutineScope.launchMesssageResendTask(
    config: Config,
    messagePendingAckRepository: MessagePendingAckRepository,
    payloadMessageForwardingService: PayloadMessageForwardingService,
    meterRegistry: MeterRegistry,
    leadership: Leadership
) {
    val metrics = BackgroundJobMetrics(meterRegistry, "ack-resend")
    launchLeaderSchedule(
        name = "ACK resends",
        startupDelay = config.messageResendPolicy.startupDelay,
        interval = config.messageResendPolicy.processInterval,
        leadership = leadership
    ) {
        metrics.record {
            log.info("=== MessageResendTask starting...")
            val messagesToResend = messagePendingAckRepository.findMessagesToResend()
            log.info("Found ${messagesToResend.size} messages to be resent because of missing Ack")
            for (message in messagesToResend) {
                if (!leadership.isLeader) throw no.nav.emottak.ebms.async.leadership.BackgroundJobUnavailable("ACK resend leadership lost")
                payloadMessageForwardingService.resendMessage(message)
                meterRegistry.incrementMessagesResent(
                    resentCount = message.resentCount + 1,
                    service = message.messageHeader.service.value ?: "unknown",
                    action = message.messageHeader.action ?: "unknown"
                )
                messagePendingAckRepository.markResent(message)
                metrics.progress()
            }
        }
    }
}

fun Application.ebmsProviderModule(
    payloadRepository: PayloadRepository,
    messageFilterService: MessageFilterService,
    eventRegistrationService: EventRegistrationService,
    retryService: RetryService,
    payloadMessageService: PayloadMessageService,
    pauseRetryErrorsTimerFlag: PauseRetryErrorsTimerFlag,
    messagePendingAckRepository: MessagePendingAckRepository,
    appMicrometerRegistry: PrometheusMeterRegistry,
    leaderForwarder: LeaderForwarder? = null
) {
    installMicrometerRegistry(appMicrometerRegistry)
    installContentNegotiation()
    installAuthentication()

    routing {
        registerRootEndpoint()
        registerHealthEndpoints()
        registerPrometheusEndpoint(appMicrometerRegistry)
        registerNavCheckStatus()
        redeliverToSendIn()
        forceRetryMessageIn(retryService)
        forceRetryMessageOut(retryService)
        retryErrorsIncoming(retryService, messageFilterService, leaderForwarder)
        retryErrorsOutgoing(retryService, payloadMessageService, leaderForwarder)
        rerunIncoming(retryService, messageFilterService)
        rerunOutgoing(retryService, payloadMessageService)
        rerunOutgoingInterval(retryService, payloadMessageService)
        pauseRetries(pauseRetryErrorsTimerFlag)
        resumeRetries(pauseRetryErrorsTimerFlag)
        unacknowledge(messagePendingAckRepository)
        getMessagesPendingAck(messagePendingAckRepository)
        getMessagesPendingAckHtml(messagePendingAckRepository)
        authenticate(AZURE_AD_AUTH) {
            getPayloads(payloadRepository, eventRegistrationService)
        }
    }
}
